// Back to top functionality
window.addEventListener('load', function() {
    const backToTop = document.createElement('button');
    backToTop.className = 'back-to-top';
    const icon = document.createElement('i');
    icon.className = 'fas fa-arrow-up';
    backToTop.appendChild(icon);
    backToTop.setAttribute('aria-label', 'Back to top');
    backToTop.style.display = 'none';
    document.body.appendChild(backToTop);
    
    backToTop.addEventListener('click', function() {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    });
});

// Scroll effect to header and back-to-top button - consolidated implementation
window.addEventListener('scroll', function() {
    const header = document.querySelector('.main-header');
    const backToTop = document.querySelector('.back-to-top');
    
    if (!header) return;
    
    const scrollY = window.scrollY;
    
    // Direction-aware header hiding (hide on scroll down, show on scroll up)
    let lastScrollPosition = header.dataset.lastScroll || 0;
    
    if (scrollY > lastScrollPosition && scrollY > 100) {
        // Scrolling down - hide header
        header.classList.add('hidden');
    } else {
        // Scrolling up - show header
        header.classList.remove('hidden');
    }
    
    header.dataset.lastScroll = scrollY;
    
    // Back-to-top visibility
    if (backToTop) {
        if (scrollY > 300) {
            backToTop.classList.add('visible');
        } else {
            backToTop.classList.remove('visible');
        }
    }
}, { passive: true });

// Add touch device class for CSS-based touch styling
window.addEventListener('load', function() {
    const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
    if (isTouchDevice) {
        document.body.classList.add('touch-device');
    }
});
